<script lang="ts">
	import { page } from "$app/state";
	import { activeView, type AppView } from "$lib/states/windowState.svelte";
	import Toolbar from "$lib/components/Toolbar.svelte";
	import SurfaceNotes from '$lib/modules/notes/NotesModule.svelte'
	import SurfaceBench from '$lib/modules/observ/Observatory.svelte'
	import { Icon } from "fractalicons";
	import {
		luBookOpen,
		luFilePlus,
		luFolderOpen,
		luPin,
		luX,
	} from "fractalicons/lucide";
	import { openFile, newDocument } from "$lib/tauri/files";
	import "$lib/styles/index.sass";
	import { ThemeScript, AuraBackground, ThemePicker } from "fractalthemer";
	import "fractalthemer/styles.css";
	let { children } = $props();
	const tabs: AppView[] = ["notes", "bench", "agents", "canvas"];
	const mode = $derived(
		page.url.pathname.startsWith("/observatory")
			? "observatory"
			: "knowledge",
	);
</script>

<ThemeScript />
<AuraBackground />
<div class="app-shell">
	<header class="app-header row gap-16 xbetween">
		<nav class="row gap-16">
			{#each tabs as tab}
				<button
					class="button small text-sm tt-u"
					class:active={activeView.is(tab)}
					onclick={() => activeView.set(tab)}
				>
					{tab}
				</button>
			{/each}
		</nav>
		<nav class="row gap-16">
			{#if activeView.is("notes")}
				<button class="button is-icon" onclick={newDocument}>
					<Icon icon={luFilePlus} size={16} />
				</button>
			{/if}
			<ThemePicker />
		</nav>
	</header>
	<main class="app-main">
		{#if activeView.is("notes")}
		<SurfaceNotes/>
		{:else if activeView.is("bench")}
		<SurfaceBench/>
		{:else}
		{@render children()}
		{/if}
	</main>
</div>

