1321:	:global(.md-content)

---md first 15 lines---
// =============================================================================
// 11_MARKDOWN-CONTENT — Styles for the rendered Markdown article. Owns the
// typography, code blocks (incl. the highlight.js dark-theme color mirror),
// tables, blockquotes, images, links, KaTeX math, and Mermaid diagrams.
// All classes here are descendant of .md-content (the article wrapper in
// MarkdownRenderer). Generated <mark>s, tooltips, and copy buttons ride the
// shared search/lightbox/tooltip classes in 09.
// =============================================================================

@use 'sass:map'
@use '01_config' as *

// Base article
.md-content
	color: var(--text-primary)

