{"code":"const read = (path) => tools.read({ file_path: path });
const write = (path, content) => tools.write({ file_path: path, content });
const root = '/Users/amrit/fractalmandala/fracta-era1';

// Read full markdown-content
const md = await read(`${root}/src/lib/styles/_11_markdown-content.sass`);
const mdContent = md.lines.map(l => l.text).join('\n');

// Update the .md-content rule to add font-family
const updated = mdContent.replace(
  `.md-content
	color: var(--text-primary)
	max-width: var(--content-max, 720px)
	margin: 0 auto
	padding: var(--space-md) var(--space-md)
	transition: max-width var(--motion-base) var(--ease-out), font-size var(--motion-base) var(--ease-out), font-family var(--motion-base) var(--ease-out)`,
  `.md-content
	color: var(--text-primary)
	max-width: var(--content-max, 720px)
	margin: 0 auto
	padding: var(--space-md) var(--space-md)
	font-family: var(--md-font-family, inherit)
	transition: max-width var(--motion-base) var(--ease-out), font-size var(--motion-base) var(--ease-out), font-family var(--motion-base) var(--ease-out)`
);

await write(`${root}/src/lib/styles/_11_markdown-content.sass`, updated);
console.log('Updated md-content sass');

// Verify by re-reading
const verify = await read(`${root}/src/lib/styles/_11_markdown-content.sass`);
console.log(verify.lines.slice(8, 16).map(l => l.text).join('\n'));","description":"Update markdown-content sass for font-family var"}

