{"code":"const read = (path) => tools.read({ file_path: path });
const edit = (path, old_string, new_string) => tools.edit({ file_path: path, old_string, new_string });
const root = '/Users/amrit/fractalmandala/fracta-era1';

// 1. ProgressBar - dynamic width
await read(`${root}/src/lib/components/ProgressBar.svelte`);
await edit(`${root}/src/lib/components/ProgressBar.svelte`,
  `<div class="progress-bar" style="width: {progress}%"></div>`,
  `<div class="progress-bar" style="--progress: {progress}%"></div>`
);

// 2. EmptyState - zoom scale
await read(`${root}/src/lib/components/EmptyState.svelte`);
await edit(`${root}/src/lib/components/EmptyState.svelte`,
  `<div class="empty-root" style="zoom: {scale};">`,
  `<div class="empty-root" style="--zoom: {scale};">`
);

// 3. TableOfContents - padding-left based on level
await read(`${root}/src/lib/components/TableOfContents.svelte`);
await edit(`${root}/src/lib/components/TableOfContents.svelte`,
  `style="padding-left: calc(12px + {getIndent(entry.level)})"`,
  `style="--toc-indent: {getIndent(entry.level)}"`
);

// 4. ReaderControls - hardcoded margin-bottom
await read(`${root}/src/lib/components/ReaderControls.svelte`);
await edit(`${root}/src/lib/components/ReaderControls.svelte`,
  `<div class="rc-group" class:disabled={$settings.widthMode === "wide"} style="margin-bottom: 0;">`,
  `<div class="rc-group rc-group-last" class:disabled={$settings.widthMode === "wide"}>`
);

// 5. Toolbar - hardcoded font-size
await read(`${root}/src/lib/components/Toolbar.svelte`);
await edit(`${root}/src/lib/components/Toolbar.svelte`,
  `<span style="font-size:11px">{copyFeedback}</span>`,
  `<span class="copy-feedback">{copyFeedback}</span>`
);

// 6. TabBar - dynamic dropdown position
await read(`${root}/src/lib/components/TabBar.svelte`);
await edit(`${root}/src/lib/components/TabBar.svelte`,
  `<div class="dropdown" style="left: {contextMenuPos.x}px; top: {contextMenuPos.y}px;">`,
  `<div class="dropdown" style="--dropdown-x: {contextMenuPos.x}px; --dropdown-y: {contextMenuPos.y}px;">`
);

console.log('Updated 6 components');","description":"Update inline styles in 6 components"}

