---NotesModule markup---

<div class="page-split">
	<aside class="page-sidebar">
				<KnowledgeLibrary
				onOpen={() => (openVisible = true)}
				onPaste={() => {
					pasteDefaultMode = "paste";
					pasteVisible = true;
				}}
				onUrl={() => {
					pasteDefaultMode = "url";
					pasteVisible = true;
				}}
			/>
	</aside>
	<section class="page-main">
		{#if !zenMode}
			<ProgressBar />
			<Toolbar
				onOpen={() => (openVisible = true)}
				onPaste={() => {
					pasteDefaultMode = "paste";
					pasteVisible = true;
				}}
				onUrl={() => {
					pasteDefaultMode = "url";
					pasteVisible = true;
				}}
				{rawMode}
				onRawToggle={handleRawToggle}
				isEditing={activeTab?.isEditing ?? false}
				dirty={activeTab?.dirty ?? false}
				canEdit={canEditActive}
				editMode={activeEditMode}
				onSetMode={setMode}
				onSave={() => activeTab && handleSave(activeTab)}
				onOpenSettings={() => (settingsVisible = true)}
				canPresent={activeIsMarp}
				{presenting}
				onTogglePresent={togglePresent}
			/>
			<TabBar onCloseTab={handleCloseTab} />
		{/if}
		<DropZone />
		{#if !zenMode && !activeTab?.isEditing}
			<TableOfContents />
		{/if}
		<SearchOverlay bind:visible={searchVisible} />
		<PasteModal
			bind:visible={pasteVisible}
			defaultMode={pasteDefaultMode}
		/>
		<OpenDialog bind:visible={openVisible} />
		<SettingsDialog bind:visible={settingsVisible} />
		<AboutDialog bind:visible={aboutVisible} />
		<CustomPromptModal
			bind:visible={customPromptVisible}
			selection={customPromptSelection}
		/>

		{#if !rendererReady}
			<div class="state-center">
				<p class="state-text pulse">Loading renderer...</p>
			</div>
		{:else if $docStore.loading}
			<div class="state-center">
				<p class="state-text pulse">Opening file...</p>
			</div>
		{:else if $docStore.error}
			<div class="state-center">
				<div class="error-box">
					<svg
						width="24"
						height="24"
						viewBox="0 0 24 24"
						fill="none"
						stroke="#ff3b30"
						stroke-width="1.5"
						stroke-linecap="round"
						><circle cx="12" cy="12" r="10" /><line
							x1="12"
							y1="8"
							x2="12"
							y2="12"
						/><line x1="12" y1="16" x2="12.01" y2="16" /></svg
					>
					<p class="error-msg">{$docStore.error}</p>
				</div>
			</div>
		{:else if $docStore.filePath}
			<!-- Gate on filePath, not renderedHtml: an empty file renders to empty HTML,
         and gating on that dropped the user back to the home/recents view with no
         way to edit (#52). A real (even empty) file tab always shows here. -->
			{#if presenting && activeIsMarp}
				<PresentationView
					content={$docStore.content}
					baseDir={activeTab ? getBaseDir(activeTab.filePath) : ""}
					paginate={activePaginate}
					onExit={() => (presenting = false)}
					onLocalLink={handleLocalLink}
				/>
			{:else if activeTab?.isEditing && splitMode}
				<div class="knowledge-edit-layout split">
					<Editor
						value={activeTab.editContent}
						onChange={(v) =>
							tabStore.updateEditContent(activeTab!.id, v)}
						fontSize={$settings.fontSize}
						lineHeight={$settings.lineHeight}
						maxWidth="100%"
						showLineNumbers={$settings.showLineNumbers}
						split
					/>
					<main class="split-preview">
						<MarkdownRenderer
							html={splitPreviewHtml}
							onImageClick={(src, all, idx) => {
								lightboxImages = all;
								lightboxIndex = idx;
								lightboxVisible = true;
							}}
							onLocalLink={handleLocalLink}
						/>
					</main>
				</div>
			{:else if activeTab?.isEditing}
				<div class="knowledge-edit-layout">
					<Editor
						value={activeTab.editContent}
						onChange={(v) =>
							tabStore.updateEditContent(activeTab!.id, v)}
						fontSize={$settings.fontSize}
						lineHeight={$settings.lineHeight}
						maxWidth={contentMaxWidth}
						showLineNumbers={$settings.showLineNumbers}
					/>
				</div>
			{:else if rawMode}
				<main
					class="content-main"
					class:toc-spaced={$tocVisible && $tocEntries.length > 0}
				>
					<pre
						class="raw-source"
						style="--raw-font-size: {$settings.fontSize}px; --raw-line-height: {$settings.lineHeight}; --raw-max-width: {contentMaxWidth};"><code
							>{$docStore.content}</code
						></pre>
				</main>
			{:else}
				<main
					class="content-main"
					class:toc-spaced={$tocVisible && $tocEntries.length > 0}
				>
					<FrontmatterBar />
					<MarkdownRenderer
						html={$docStore.renderedHtml}
						onImageClick={(src, all, idx) => {
							lightboxImages = all;
							lightboxIndex = idx;
							lightboxVisible = true;
						}}
						onLocalLink={handleLocalLink}
					/>
				</main>
			{/if}
			{#if !zenMode && !activeTab?.isEditing && !presenting}
				<StatusBar />
				<ScrollToTop />
			{/if}
			<ImageLightbox
				bind:visible={lightboxVisible}
				src=""
				images={lightboxImages}
				bind:index={lightboxIndex}
			/>
		{:else}
			<EmptyState
				onOpenUrl={() => {
					pasteDefaultMode = "url";
					pasteVisible = true;
				}}
			/>
		{/if}
		<Toast />
	</section>
</div>

