      {#each entries as [key, value]}
        <div class="row ycenter gap-3xs">
          <span class="fm-key text-xs weight-600 tt-u text-muted">{key}</span>
          <span class="text-sm text-secondary">{value}</span>
        </div>
      {/each}
    </div>
  {/if}
{/if}
`;
