<script lang="ts">
	import { invoke } from '@tauri-apps/api/core';
	import { open } from '@tauri-apps/plugin-dialog';
	import { Icon } from 'fractalicons';
	import { luBookOpen, luFilePlus, luFolderOpen, luPin, luX } from 'fractalicons/lucide';
	import { openFile, newDocument } from '$lib/tauri/files';
	import { pinnedFolders } from '$lib/stores/pinned';
	import { recentFiles, removeRecentFile } from '$lib/stores/recents';

	let {
		onPaste = () => {},
		onOpen = () => {},
		onUrl = () => {}
	}: {
		onPaste?: () => void;
		onOpen?: () => void;
		onUrl?: () => void;
	} = $props();

	interface MdFile {
		name: string;
		path: string;
		rel_path: string;
		modified: number;
	}

	let folderFiles = $state<Record<string, MdFile[]>>({});
	let expandedFolders = $state<Set<string>>(new Set());

	$effect(() => {
		for (const folder of $pinnedFolders) {
			if (folder in folderFiles) continue;
			void loadFolder(folder);
		}
	});

	async function loadFolder(folder: string) {
		try {
			const files = await invoke<MdFile[]>('list_folder_md_files', { folder, maxDepth: 3 });
			folderFiles = { ...folderFiles, [folder]: files };
		} catch {
			folderFiles = { ...folderFiles, [folder]: [] };
		}
	}

	async function addPinnedFolder() {
		try {
			const selected = await open({ directory: true, multiple: false });
			if (!selected || typeof selected !== 'string') return;
			pinnedFolders.add(selected);
			await loadFolder(selected);
			expandedFolders = new Set([...expandedFolders, selected]);
		} catch {
			// Cancelling the native picker is an intentional no-op.
		}
	}

	function toggleFolder(path: string) {
		const next = new Set(expandedFolders);
		if (next.has(path)) next.delete(path);
		else next.add(path);
		expandedFolders = next;
	}

	function unpin(path: string) {
		pinnedFolders.remove(path);
		const { [path]: _removed, ...remaining } = folderFiles;
		folderFiles = remaining;
		const next = new Set(expandedFolders);
		next.delete(path);
		expandedFolders = next;
	}

	function folderName(path: string) {
		return path.replace(/\/+$/, '').split('/').pop() || path;
	}

	function relativeTime(timestamp: number) {
		const elapsed = Math.max(0, Date.now() - timestamp);
		const minutes = Math.floor(elapsed / 60_000);
		if (minutes < 1) return 'now';
		if (minutes < 60) return `${minutes}m`;
		const hours = Math.floor(minutes / 60);
		if (hours < 24) return `${hours}h`;
		const days = Math.floor(hours / 24);
		return days < 7 ? `${days}d` : new Date(timestamp).toLocaleDateString();
	}
</script>

<aside class="sidebar-left" aria-label="Notes library">
	<div class="knowledge-library-actions">
		<div class="knowledge-library-secondary-actions">
			<button class="button small ghost" onclick={onOpen}>Open</button>
			<button class="button small ghost" onclick={onPaste}>Paste</button>
			<button class="button small ghost" onclick={onUrl}>URL</button>
		</div>
	</div>

	<section class="knowledge-library-section" aria-labelledby="pinned-folders-heading">
		<div class="knowledge-library-heading">
			<h2 id="pinned-folders-heading">Pinned folders</h2>
			<button class="knowledge-library-icon-action" onclick={addPinnedFolder} title="Pin folder" aria-label="Pin folder">
				<Icon icon={luPin} size={14} />
			</button>
		</div>
		{#if $pinnedFolders.length === 0}
			<p class="knowledge-library-empty">Pin a folder to keep its recent Markdown files within reach.</p>
		{:else}
			<ul class="knowledge-library-list">
				{#each $pinnedFolders as folder (folder)}
					<li>
						<div class="knowledge-library-folder-row">
							<button class="knowledge-library-folder-button" onclick={() => toggleFolder(folder)} aria-expanded={expandedFolders.has(folder)}>
								<Icon icon={luFolderOpen} size={15} />
								<span>{folderName(folder)}</span>
								<span class="knowledge-library-count">{folderFiles[folder]?.length ?? '…'}</span>
							</button>
							<button class="knowledge-library-remove" onclick={() => unpin(folder)} aria-label={`Unpin ${folderName(folder)}`} title="Unpin folder">
								<Icon icon={luX} size={13} />
							</button>
						</div>
						{#if expandedFolders.has(folder)}
							<ul class="knowledge-library-files">
								{#if !folderFiles[folder]}
									<li class="knowledge-library-empty">Loading files…</li>
								{:else if folderFiles[folder].length === 0}
									<li class="knowledge-library-empty">No Markdown files found.</li>
								{:else}
									{#each folderFiles[folder] as file (file.path)}
										<li>
											<button class="knowledge-library-file" onclick={() => void openFile(file.path)} title={file.rel_path}>
												<Icon icon={luBookOpen} size={13} />
												<span>{file.rel_path}</span>
											</button>
										</li>
									{/each}
								{/if}
							</ul>
						{/if}
					</li>
				{/each}
			</ul>
		{/if}
	</section>

	<section class="knowledge-library-section" aria-labelledby="recent-notes-heading">
		<div class="knowledge-library-heading">
			<h2 id="recent-notes-heading">Recent</h2>
			<span class="knowledge-library-count">{$recentFiles.length}</span>
		</div>
		{#if $recentFiles.length === 0}
			<p class="knowledge-library-empty">Notes you open will appear here.</p>
		{:else}
			<ul class="knowledge-library-list">
				{#each $recentFiles as file (file.path)}
					<li class="knowledge-library-recent-row">
						<button class="knowledge-library-recent" onclick={() => void openFile(file.path)} title={file.path}>
							<Icon icon={luBookOpen} size={14} />
							<span class="knowledge-library-recent-copy">
								<span>{file.name}</span>
								<small>{relativeTime(file.openedAt)} ago</small>
							</span>
						</button>
						<button class="knowledge-library-remove" onclick={() => removeRecentFile(file.path)} aria-label={`Remove ${file.name} from recents`} title="Remove from recents">
							<Icon icon={luX} size={13} />
						</button>
					</li>
				{/each}
			</ul>
		{/if}
	</section>
</aside>

