const root = '/Users/amrit/fractalmandala/fracta-era1';

// Read all component class= usage to audit
const comps = [
  'Toolbar.svelte', 'MarkdownRenderer.svelte', 'DropZone.svelte', 'EmptyState.svelte',
  'TableOfContents.svelte', 'TabBar.svelte', 'SearchOverlay.svelte', 'PasteModal.svelte',
  'OpenDialog.svelte', 'SettingsDialog.svelte', 'AboutDialog.svelte', 'CustomPromptModal.svelte',
  'FrontmatterBar.svelte', 'StatusBar.svelte', 'ProgressBar.svelte', 'ScrollToTop.svelte',
  'ImageLightbox.svelte', 'Toast.svelte', 'Editor.svelte', 'PresentationView.svelte',
  'AILookupSettings.svelte', 'ReaderControls.svelte', 'KnowledgeLibrary.svelte',
];

const report = {};
for (const c of comps) {
  const r = await read(`${root}/src/lib/components/${c}`);
  // Extract class= attributes
  const classLines = r.lines.filter(l => l.text.includes('class="'));
  report[c] = classLines.map(l => l.text.match(/class="([^"]+)"/g) || []).flat();
}

// Audit: any non-fractalstyler2 classes being used?
