  // (keep for lightbox/menu where depth cues are useful)
  ['shadow-md', ''],
  ['shadow-lg', ''],
];

const files = [
  'src/lib/components/Toast.svelte',
  'src/lib/components/Editor.svelte',
  'src/lib/components/ScrollToTop.svelte',
  'src/lib/components/ReaderControls.svelte',
  'src/lib/components/TableOfContents.svelte',
  'src/lib/components/SearchOverlay.svelte',
  'src/lib/components/Toolbar.svelte',
  'src/lib/components/PresentationView.svelte',
  'src/lib/components/TabBar.svelte',
  'src/lib/components/ImageLightbox.svelte',
  'src/lib/components/DropZone.svelte',
  'src/lib/components/EmptyState.svelte',
  'src/lib/components/SettingsDialog.svelte',
  'src/lib/components/OpenDialog.svelte',
  'src/lib/components/AboutDialog.svelte',
  'src/lib/components/CustomPromptModal.svelte',
  'src/lib/components/AILookupSettings.svelte',
  'src/lib/components/PasteModal.svelte',
  'src/lib/components/KnowledgeLibrary.svelte',
];

for (const f of files) {
  const fullPath = path.join(root, f);
  let content = fs.readFileSync(fullPath, 'utf8');
  let changed = false;
  for (const [from, to] of replacements) {
    // Use a word-boundary-aware replacement on class names
    const re = new RegExp('\\\\b' + from + '\\\\b', 'g');
    const before = content;
    content = content.replace(re, to);
    if (content !== before) {
      changed = true;
      // Collapse double spaces from removed classes
      content = content.replace(/\\\\s{2,}/g, ' ');
    }
  }
  // Clean up double spaces and trailing spaces in class lists
  content = content.replace(/class="\\\\s+/g, 'class="');
  content = content.replace(/\\\\s+"/g, '"');
  if (changed) {
    fs.writeFileSync(fullPath, content);
    console.log('Updated:', f);
  }
}
console.log('Sweep complete');
`;

await write('/tmp/sweep.js', sweep);
const r = await bash(`node /tmp/sweep.js`, 'sweep classes', root);
console.log(r.stdout.text);
