const fs = require('fs');
const path = require('path');
const root = '/Users/amrit/fractalmandala/fracta-era1';
const files = [
  'src/lib/components/Editor.svelte',
  'src/lib/components/PresentationView.svelte',
  'src/lib/components/FrontmatterBar.svelte',
];
for (const f of files) {
  const fp = path.join(root, f);
  let c = fs.readFileSync(fp, 'utf8');
  let changed = false;
  // bg-popover -> bg
  const before = c;
  c = c.replace(/\\bbg-popover\\b/g, 'bg');
  if (c !== before) { changed = true; console.log('bg-popover->bg in', f); }
  // bg-surface -> bg  
  const before2 = c;
  c = c.replace(/\\bbg-surface\\b/g, 'bg');
  if (c !== before2) { changed = true; console.log('bg-surface->bg in', f); }
  // max-w-720 -> max-w-measure (a token-driven class)
  const before3 = c;
  c = c.replace(/\\bmax-w-720\\b/g, 'max-w-measure');
  if (c !== before3) { changed = true; console.log('max-w-720->max-w-measure in', f); }
  if (changed) fs.writeFileSync(fp, c);
}

