const fs = require("fs");
const path = require("path");
const root = process.argv[2];
const files = process.argv.slice(3);
for (const f of files) {
  const fp = path.join(root, f);
  let c = fs.readFileSync(fp, "utf8");
  let changed = false;
  const rep = (from, to, label) => {
    const re = new RegExp("\\b" + from + "\\b", "g");
    const before = c;
    c = c.replace(re, to);
    if (c !== before) { changed = true; console.log(label, "in", f); }
  };
  rep("bg-popover", "bg", "bg-popover->bg");
  rep("bg-surface", "bg", "bg-surface->bg");
  rep("max-w-720", "max-w-measure", "max-w-720->max-w-measure");
  if (changed) fs.writeFileSync(fp, c);
}

const fs = require("fs");
const path = require("path");
const root = process.argv[2];
const files = process.argv.slice(3);
for (const f of files) {
  const fp = path.join(root, f);
  let c = fs.readFileSync(fp, "utf8");
  let changed = false;
  const rep = (from, to, label) => {
    const re = new RegExp("\\b" + from + "\\b", "g");
    const before = c;
    c = c.replace(re, to);
    if (c !== before) { changed = true; console.log(label, "in", f); }
  };
  rep("bg-popover", "bg", "bg-popover->bg");
  rep("bg-surface", "bg", "bg-surface->bg");
  rep("max-w-720", "max-w-measure", "max-w-720->max-w-measure");
  if (changed) fs.writeFileSync(fp, c);
}

