content.text:
===== observatory/ActivityView.svelte (5 lines) =====
<script lang="ts">
	import { observatory } from '$lib/observatory-state/observatory.svelte';
	let rows = $derived(observatory.activityCalendar);
</script>
<section class="resource-view"><h2>Activity</h2><p>Calendar-day buckets use the selected local timezone and active Fractorches filter.</p><table><thead><tr><th>Date</th><th>Sessions</th><th>Messages</th><th>Tool calls</th></tr></thead><tbody>{#each rows as row (row.date)}<tr><td>{row.date}</td><td>{row.sessions}</td><td>{row.messages}</td><td>{row.tool_calls}</td></tr>{:else}<tr><td colspan="4">No activity was reported for this filter.</td></tr>{/each}</tbody></table><h3>Hour of week</h3><ul>{#each observatory.hourlyMatrix as cell (`${cell.day_of_week}-${cell.hour}`)}<li>Day {cell.day_of_week}, {cell.hour}:00 — {cell.messages} messages</li>{:else}<li>No hourly activity was reported.</li>{/each}</ul></section>

===== observatory/ModelBreakdownTable.svelte (6 lines) =====
<script lang="ts">
	import { observatory } from '$lib/observatory-state/observatory.svelte';
	const dollars = (microdollars: number) => (microdollars / 1_000_000).toFixed(2);
	let models = $derived(observatory.modelBreakdown);
</script>
<section class="model-breakdown" aria-labelledby="models-title"><header><h3 id="models-title">Model breakdown</h3><p>Only model totals reported by the canonical usage endpoint are shown.</p></header><table><thead><tr><th>Model</th><th>Input</th><th>Output</th><th>Cache read</th><th>Cost</th></tr></thead><tbody>{#each models as row}<tr><td>{row.model}</td><td>{row.inputTokens.toLocaleString()}</td><td>{row.outputTokens.toLocaleString()}</td><td>{row.cacheReadTokens.toLocaleString()}</td><td>${dollars(row.cost.microdollars)}</td></tr>{:else}<tr><td colspan="5">No model usage reported for this filter.</td></tr>{/each}</tbody></table></section>

===== observatory/PinnedView.svelte (2 lines) =====
<script lang="ts">import { observatory } from '$lib/observatory-state/observatory.svelte';</script>
<section class="resource-view"><h2>Pinned messages</h2>{#each observatory.pinnedMessages as pin (pin.id)}<article><strong>{pin.session_display_name || pin.session_first_message || pin.session_id}</strong><p>{pin.content || 'Pinned message content is unavailable from this record.'}</p><small>{pin.session_project} · {pin.session_agent} · {pin.created_at}</small><button onclick={() => observatory.togglePinMessage(pin)}>Unpin</button></article>{:else}<p>No messages are pinned in Fractorches.</p>{/each}</section>

===== observatory/ProjectsDataTable.svelte (2 lines) =====
<script lang="ts">import { observatory } from '$lib/observatory-state/observatory.svelte';</script>
<section class="resource-view"><h2>Project inventory</h2><label>Find project <input bind:value={observatory.dataProjectFilter} /></label><table><thead><tr><th>Project</th><th>Sessions</th><th>Messages</th><th>Average messages</th><th>First session</th><th>Last session</th></tr></thead><tbody>{#each observatory.projectsTable.filter((row) => row.name.toLowerCase().includes(observatory.dataProjectFilter.toLowerCase())) as row (row.name)}<tr><td>{row.name}</td><td>{row.sessions}</td><td>{row.messages}</td><td>{row.avg_messages}</td><td>{row.first_session}</td><td>{row.last_session}</td></tr>{:else}<tr><td colspan="6">No canonical project analytics match this filter.</td></tr>{/each}</tbody></table></section>

===== observatory/TopSkillsCard.svelte (6 lines) =====
<script lang="ts">
	import { observatory } from '$lib/observatory-state/observatory.svelte';
	let skills = $derived(observatory.topSkills);
	let tools = $derived(observatory.toolUsage);
</script>
<section class="trends"><header><p class="eyebrow">Canonical trends</p><h2>Skills and tools</h2><p class="muted">Counts and shares are returned by Fractorches for the active filter.</p></header><h3>Skills</h3><table><thead><tr><th>Skill</th><th>Calls</th><th>Sessions</th><th>Share</th><th>Last used</th></tr></thead><tbody>{#each skills as row}<tr><td>{row.skill_name}</td><td>{row.call_count}</td><td>{row.session_count}</td><td>{(row.pct * 100).toFixed(1)}%</td><td>{row.last_used_at}</td></tr>{:else}<tr><td colspan="5">No skills reported.</td></tr>{/each}</tbody></table><h3>Tools</h3><table><thead><tr><th>Tool</th><th>Category</th><th>Calls</th><th>Sessions</th><th>Share</th></tr></thead><tbody>{#each tools as row}<tr><td>{row.tool_name}</td><td>{row.category}</td><td>{row.call_count}</td><td>{row.session_count}</td><td>{(row.pct * 100).toFixed(1)}%</td></tr>{:else}<tr><td colspan="5">No tools reported.</td></tr>{/each}</tbody></table></section>

