    else if (e.name.endsWith(".svelte")) out.push(p);
  }
  return out;
}

const files = walk(path.join(root, "src/lib/observatory-components"));
let kept = 0, hardcoded = [];
for (const f of files) {
  const c = fs.readFileSync(f, "utf8");
  const re = /style="([^"]*)"/g;
  let m;
  while ((m = re.exec(c)) !== null) {
    const val = m[1];
    const onlyVars = val.split(";").every(s => {
      s = s.trim();
      if (!s) return true;
      return /^--[a-z][a-z0-9-]*\s*:/.test(s) || /^var\(--/.test(s) || s.startsWith("--") || /^[a-z-]+: var\(--/.test(s);
    });
    if (onlyVars) {
      kept++;
    } else {
      hardcoded.push(f + ": " + val);
    }
  }
}
console.log("CSS-var-only inline styles:", kept);
console.log("Hardcoded inline styles found:", hardcoded.length);
for (const h of hardcoded) console.log("  " + h);

