{"code":"const read = (path) => tools.read({ file_path: path });
const edit = (path, old_string, new_string) => tools.edit({ file_path: path, old_string, new_string });
const bash = (cmd, desc) => tools.bash({ command: cmd, description: desc });
const root = '/Users/amrit/fractalmandala/fracta-era1';

await read(`${root}/src/lib/observatory-components/observatory/RecallView.svelte`);
await edit(`${root}/src/lib/observatory-components/observatory/RecallView.svelte`,
  `<label class="row ycenter gap-2xs text-sm text-secondary grow min0" style="max-width: 320px;">`,
  `<label class="row ycenter gap-2xs text-sm text-secondary grow min0 recall-search">`
);

await read(`${root}/src/lib/observatory-components/logs/LogTimeline.svelte`);
await edit(`${root}/src/lib/observatory-components/logs/LogTimeline.svelte`,
  `<input\n				type="text"\n				placeholder="Search entries…"\n				bind:value={searchFilter}\n				class="input text-sm shrink-0"\n				style="width: min(92vw, 16rem);"\n			/>`,
  `<input\n				type="text"\n				placeholder="Search entries…"\n				bind:value={searchFilter}\n				class="input text-sm shrink-0 recall-search-input"\n			/>`
);

await read(`${root}/src/lib/observatory-components/shell/ThemeCustomizer.svelte`);
await edit(`${root}/src/lib/observatory-components/shell/ThemeCustomizer.svelte`,
  `<div class="dialog-card card radius-lg bg-dialog border shadow-lg box dialog-md" style="width: min(92vw, 32rem);">`,
  `<div class="dialog-card card radius-lg bg-dialog border shadow-lg box dialog-md dialog-theme-customizer">`
);

// Update the swatch to use the class name with --var from data, plus an inline custom prop
await edit(`${root}/src/lib/observatory-components/shell/ThemeCustomizer.svelte`,
  `<div class="preset-swatch border shrink-0" style="background: {p.bg}; border-color: {p.border};"></div>`,
  `<div class="preset-swatch border shrink-0" style="background: {p.bg}; --swatch-border: {p.border};"></div>`
);

await edit(`${root}/src/lib/observatory-components/shell/ThemeCustomizer.svelte`,
  `<button\n							class="accent-swatch"\n							class:accent-swatch-active={themeState.config.accent === color.val}\n							style="background: {color.val};"\n							title={color.name}\n							onclick={() => themeState.setAccent(color.val)}\n						></button>`,
  `<button\n							class="accent-swatch"\n							class:accent-swatch-active={themeState.config.accent === color.val}\n							style="--swatch-color: {color.val};"\n							title={color.name}\n							onclick={() => themeState.setAccent(color.val)}\n						></button>`
);

// Update _08_own.sass to add the width classes
const sass = await read(`${root}/src/lib/styles/_08_own.sass`);
const sassContent = sass.lines.map(l => l.text).join('\n');

const additions = `
.recall-search
	max-width: min(100%, 20rem)
.recall-search-input
	width: min(92vw, 16rem)
.dialog-theme-customizer
	width: min(92vw, 32rem)
.preset-swatch
	border-color: var(--swatch-border, var(--border))
.accent-swatch
	background: var(--swatch-color)
`;

// Insert before // --- Spinner block
const updated = sassContent.replace(
  '// --- Spinner ---',
  additions + '\n// --- Spinner ---'
);

await write(`${root}/src/lib/styles/_08_own.sass`, updated);

// Verify
const r = await bash('pnpm exec sass --no-source-map --style=compressed src/lib/styles/index.sass /tmp/test-out.css 2>&1 | head -3', 'sass', root);
console.log('sass:', r.stdout.text || 'OK', r.exitCode);
const r2 = await bash('pnpm exec svelte-check --tsconfig ./tsconfig.json 2>&1 | grep "svelte-check found"', 'check', root);
console.log(r2.stdout.text);
const r3 = await bash('pnpm run build 2>&1 | tail -3', 'build', root);
console.log(r3.stdout.text);","description":"Final cleanup"}

