package parser

import (
	"encoding/json"
	"strings"
	"time"

	"go.kenn.io/agentsview/internal/money"
)

// AgentType identifies the AI agent that produced a session.
type AgentType string

const (
	AgentClaude         AgentType = "claude"
	AgentOpenClaude     AgentType = "openclaude"
